local config = {
  ui_story_32270401_1_dialog_content = "Paket untukmu, Rachel—",
  ui_story_32270401_2_dialog_content = "Kamu... datang jauh lebih cepat dari yang kuperkirakan.",
  ui_story_32270401_3_dialog_content = "(Huh? Apakah aku membayangkannya, atau Rachel baru saja menyembunyikan sesuatu?)",
  ui_story_32270401_4_dialog_content = "Wow, apa semua ini bagian-bagian? Apakah kamu... Oh maaf, saya tidak bermaksud mengganggu...",
  ui_story_32270401_5_dialog_content = "Tidak apa-apa, tidak ada yang perlu disembunyikan darimu di sini, kebanyakan.",
  ui_story_32270401_6_dialog_content = "Pokoknya, saya membawakan paketmu. Hah? Apakah ini semacam obat?",
  ui_story_32270401_7_dialog_content = "Kamu tidak sakit, kan?",
  ui_story_32270401_8_dialog_content = "Jangan khawatir, aku tidak. Lihat lebih dekat.",
  ui_story_32270401_9_dialog_content = "\"Tablet Nutrisi 30-in-1\"? Urgh, baunya lebih buruk dari masakan Vice...",
  ui_story_32270401_10_dialog_content = "Baunya tidak penting. Tablet nutrisi ini sebenarnya sangat berguna.",
  ui_story_32270401_11_dialog_content = "Terdiri dari tiga puluh bahan berbeda, satu tablet mengandung nilai gizi penuh dari makan malam yang sehat dan seimbang.",
  ui_story_32270401_12_dialog_content = "Mereka menghemat banyak waktu saya, terutama ketika saya sangat sibuk. Saya baru saja menyelesaikan persediaan terakhir saya, dan Serikat Kurir langsung mengirimkan yang baru. Mereka selalu dapat diandalkan—",
  ui_story_32270401_13_dialog_content = "Tunggu! Apakah kamu... Apakah kamu hanya makan ini saja selama beberapa hari terakhir? Apakah kamu tidak makan makanan sebenarnya?",
  ui_story_32270401_14_dialog_content = "Tidak sama sekali. Dengan nilai fungsional dan nutrisi dari tablet ini, tidak ada kebutuhan untuk mengonsumsi makanan tambahan.",
  ui_story_32270401_15_dialog_content = "\"Dapatkan asupan,\" katanya... Kamu tidak bisa begitu saja melewatkan makan, Rachel!",
  ui_story_32270401_16_dialog_content = "Makanan memiliki banyak manfaat lain selain nutrisi, tahu kan.",
  ui_story_32270401_17_dialog_content = "Misalnya?",
  ui_story_32270401_18_dialog_content = "Y-Ya, makan makanan yang lezat bisa sangat menyenangkan dan santai, terutama saat kamu makan bersama teman...",
  ui_story_32270401_19_dialog_content = "Aku mengerti sudut pandangmu.",
  ui_story_32270401_20_dialog_content = "(Sepertinya memang tidak begitu!)",
  ui_story_32270401_21_dialog_content = "... Sekarang aku berpikir tentang itu, sudah berhari-hari sejak terakhir kali aku melihatmu di kantin.",
  ui_story_32270401_22_dialog_content = "Dan meski aku tidak menyadari ada yang salah... Itu adalah kegagalan dari diriku sebagai tuan rumahmu.",
  ui_story_32270401_23_dialog_content = "Sudah cukup sulit bagi kamu untuk mengambil waktu libur, dan kamu bahkan memilih untuk menghabiskan liburanmu di atas Colossus...",
  ui_story_32270401_24_dialog_content = "Tidak perlu merasa begitu putus asa tentang ini.",
  ui_story_32270401_25_dialog_content = "Ah, maaf. Aku tidak menyalahkanmu atau apa pun, aku hanya ingin mengatakan...",
  ui_story_32270401_26_dialog_content = "Kamu adalah tuan rumah yang baik, dan saya telah menghabiskan waktu yang indah di sini di Colossus.",
  ui_story_32270401_27_dialog_content = "B-benarkah?",
  ui_story_32270401_28_dialog_content = "... Wah, balikannya cepat sekali.",
  ui_story_32270401_29_dialog_content = "Itu menyelesaikannya! Aku akan mentraktirmu makan malam yang enak dan hangat di Umbraton malam ini!",
  ui_story_32270401_30_dialog_content = "Itu tidak perlu. Saya masih memiliki sejumlah masalah mekanis penting yang harus diselesaikan, dan—",
  ui_story_32270401_31_dialog_content = "Jangan khawatir, itu akan baik-baik saja! Mempermasalahkan hal kecil hanya akan membuat segalanya lebih sulit, jadi mari kita lakukan saja!",
  ui_story_32270401_32_dialog_content = "Malam ini pukul tujuh di Umbraton! Pastikan kamu ada di sana!",
  ui_story_32270401_33_dialog_content = "...",
  ui_story_32270401_34_dialog_content = "(Aku sedikit gugup... Apakah aku terlalu memaksa saat mengundang Rachel untuk makan malam malam ini? Bagaimana jika dia tidak datang?)",
  ui_story_32270401_35_dialog_content = "<color=#e8d9bb>Jam pendulum di sudut restoran menunjukkan pukul tujuh.</color>",
  ui_story_32270401_36_dialog_content = "Maaf atas keterlambatan, Caelestite One.",
  ui_story_32270401_37_dialog_content = "Rachel! Kamu muncul tepat pukul tujuh!",
  ui_story_32270401_38_dialog_content = "Tentu saja. Kamu tidak boleh pernah terlambat untuk sebuah misi.",
  ui_story_32270401_39_dialog_content = "Sebuah misi?",
  ui_story_32270401_40_dialog_content = "... Itu hanya kiasan! Aku sama sekali tidak menganggap makan malam ini seperti misi atau apa pun.",
  ui_story_32270401_41_dialog_content = "Namun, aku punya urusan mendesak yang harus ditangani saat makan malam nanti.",
  ui_story_32270401_42_dialog_content = "Aku mengerti... Maaf telah mengganggumu saat kamu sangat sibuk...",
  ui_story_32270401_43_dialog_content = "Ini limun Anda, Nona.",
  ui_story_32270401_44_dialog_content = "... Aku pikir kamu mungkin haus, jadi aku memesan itu untukmu.",
  ui_story_32270401_45_dialog_content = "Terima kasih.",
  ui_story_32270401_46_dialog_content = "(Wow! Dia minum semuanya dalam satu tegukan!)",
  ui_story_32270401_47_dialog_content = "Selain itu, ada juga roti dan mentega gratis.",
  ui_story_32270401_48_dialog_content = "Terima kasih.",
  ui_story_32270401_49_dialog_content = "(Dia juga menghabiskan roti itu dalam satu gigitan! Bahkan tidak ada bekas mentega di piring!)",
  ui_story_32270401_50_dialog_content = "(Dan sekarang dia duduk tegak dengan tangan di pangkuannya, seolah-olah tidak ada yang terjadi...)",
  ui_story_32270401_51_dialog_content = "Eh... Rachel?",
  ui_story_32270401_52_dialog_content = "Ya? Ada apa, Caelestite Satu?",
  ui_story_32270401_53_dialog_content = "Kita tidak berada di pangkalan militer, kamu tahu itu, kan?",
  ui_story_32270401_54_dialog_content = "Kamu tidak dikejar waktu di sini, jadi santai saja dan nikmati makanannya, oke?",
  ui_story_32270401_55_dialog_content = "Hah? Aku tidak mengerti. Kenapa aku harus membuang waktu jika aku bisa menyelesaikan makananku hanya dalam beberapa detik?",
  ui_story_32270401_56_dialog_content = "Karena itu memungkinkan Anda benar-benar menikmati rasa makanannya.",
  ui_story_32270401_57_dialog_content = "Sesuatu yang sepele seperti rasa tidak seharusnya lebih diutamakan daripada efisiensi—",
  ui_story_32270401_58_dialog_content = "... Maaf, mungkin \"tidak penting\" agak keras. Apa yang ingin saya katakan adalah—",
  ui_story_32270401_59_dialog_content = "... Tidak apa-apa, aku mengerti. Kamu bilang kamu sedang menjalankan misi, setelah semua... Maaf.",
  ui_story_32270401_60_dialog_content = "Mungkin aku punya terlalu banyak waktu luang, jadi mudah bagi saya untuk membicarakan hal-hal seperti itu...",
  ui_story_32270401_61_dialog_content = "Haha... Bagaimana kalau kita lihat menunya? Kita belum memesan hidangan utama sama sekali.",
  ui_story_32270401_62_dialog_content = "Misi saya bukan seperti yang kamu pikirkan, PlayerName. Se-Sebenarnya...",
  ui_story_32270401_63_dialog_content = "Aku... Aku ingin memberimu sesuatu! Ini—",
  ui_story_32270401_64_dialog_content = "Meong!",
  ui_story_32270401_65_dialog_content = "Wow, dari mana kucing itu datang?",
  ui_story_32270401_66_dialog_content = "Meong, meong!",
  ui_story_32270401_67_dialog_content = "Oh tidak... Jangan biarkan dia lolos!",
  ui_story_32270401_68_dialog_content = "Hah?",
  ui_story_32270401_69_dialog_content = "Kejar kucing itu! Dia mencuri... maksudku, dia mencuri <color=#FFB400>sesuatu yang sangat penting</color>!",
  ui_story_32270401_70_dialog_content = "Di sana!",
  ui_story_32270401_71_dialog_content = "Tahan di sana, kucing!",
  ui_story_32270401_72_dialog_content = "Meong!",
  ui_story_32270401_73_dialog_content = "Ini naik ke tembok lagi! Urgh, kita tak ada tandingan untuk kemampuan memanjat kucing...",
  ui_story_32270401_74_dialog_content = "Mengejarnya seperti ini tidak akan berhasil... Hampir mustahil untuk mengikuti kucing di kota pada malam hari. Kita perlu menyusun strategi.",
  ui_story_32270401_75_dialog_content = "Strategi, huh? Biarkan saya berpikir... Saya bisa mencoba merasakan lokasinya.",
  ui_story_32270401_76_dialog_content = "Sempurna. Kamu beri tahu aku lokasinya, dan aku akan memerintahkan Pemburu Elangku untuk mengejarnya hingga buntu. Setelah itu terjebak—",
  ui_story_32270401_77_dialog_content = "Aku akan melompat keluar dan meraihnya!",
  ui_story_32270401_78_dialog_content = "Kamu cepat tanggap, Caelestite One. Mari kita mulai operasinya!",
  ui_story_32270401_79_dialog_content = "Di atap!",
  ui_story_32270401_80_dialog_content = "Meong!",
  ui_story_32270401_81_dialog_content = "Itu melompat ke tembok di sana!",
  ui_story_32270401_82_dialog_content = "Meong!",
  ui_story_32270401_83_dialog_content = "Meong... Meong? Meong, meong...",
  ui_story_32270401_84_dialog_content = "Meong, meong!",
  ui_story_32270401_85_dialog_content = "Kau tidak akan bisa kabur!",
  ui_story_32270401_86_dialog_content = "Meong! Meong, meong, meong!",
  ui_story_32270401_87_dialog_content = "Serahkan padaku, Caelestite One.",
  ui_story_32270401_88_dialog_content = "Maaf jika kami mengagetkanmu, kucing kecil.",
  ui_story_32270401_89_dialog_content = "(Suaranya dan ekspresinya tiba-tiba menjadi sangat lembut... Aku benar-benar lupa tentang sisi ini darinya.)",
  ui_story_32270401_90_dialog_content = "Bagaimana dengan beberapa goresan?",
  ui_story_32270401_91_dialog_content = "Meong! Purr...",
  ui_story_32270401_92_dialog_content = "(Kucing itu benar-benar menurunkan penjaganya!)",
  ui_story_32270401_93_dialog_content = "Sekarang, jadilah kucing yang baik dan diam... Di situ!",
  ui_story_32270401_94_dialog_content = "Kerja bagus, Rachel! Jadi apa sebenarnya \"hal penting\" ini?",
  ui_story_32270401_95_dialog_content = "I-Itu...",
  ui_story_32270401_96_dialog_content = "<color=#e8d9bb>*perut keroncongan*</color>",
  ui_story_32270401_97_dialog_content = "!",
  ui_story_32270401_98_dialog_content = "Ahh, sekarang setelah kita selesai mengejar kucing itu, aku baru menyadari betapa laparnya aku...",
  ui_story_32270401_99_dialog_content = "Maaf, ini semua salahku. Kita tidak sempat memesan makanan lebih awal...",
  ui_story_32270401_100_dialog_content = "Tunggu, sepertinya aku masih punya sesuatu... Aha, ini dia! Sebuah sandwich keju!",
  ui_story_32270401_101_dialog_content = "Rotinya sedikit remuk, tapi... Yep! Rasanya masih enak!",
  ui_story_32270401_102_dialog_content = "Meong! Meong, meong!",
  ui_story_32270401_103_dialog_content = "Kamu juga lapar, nak? Ini, kita bisa berbagi.",
  ui_story_32270401_104_dialog_content = "Meong, meong!",
  ui_story_32270401_105_dialog_content = "Sepertinya dia benar-benar menyukaimu, ya? Sini, kucing, aku punya makananmu di sini.",
  ui_story_32270401_106_dialog_content = "Aku tahu itu lucu dan semuanya, tapi jangan berikan sandwichmu seluruhnya, Rachel. Nanti tidak akan ada yang tersisa untukmu!",
  ui_story_32270401_107_dialog_content = "A-Aku tidak bermaksud... Pokoknya, ayo makan—",
  ui_story_32270401_108_dialog_content = "... Enak!",
  ui_story_32270401_109_dialog_content = "Meong! Meong!",
  ui_story_32270401_110_dialog_content = "Apa, kamu mau tambah? Untuk anak kecil, kamu memang punya nafsu makan yang besar. Apakah ini cukup untukmu?",
  ui_story_32270401_111_dialog_content = "Heheh...",
  ui_story_32270401_112_dialog_content = "Apanya yang lucu?",
  ui_story_32270401_113_dialog_content = "Aku ingat ada seseorang yang bilang padaku untuk tidak memberi makan kucing, dan sekarang dia memberinya semua makanannya.",
  ui_story_32270401_114_dialog_content = "Itu-Itu hanya karena kita menakutinya sangat buruk tadi! Lagipula, aku masih punya banyak! Lihat?",
  ui_story_32270401_115_dialog_content = "... Apakah kamu selalu membawa makanan kering sebanyak ini?",
  ui_story_32270401_116_dialog_content = "Kamu tidak tahu apa yang sudah aku lalui, Rachel...",
  ui_story_32270401_117_dialog_content = "Heh...",
  ui_story_32270401_118_dialog_content = "(Dia tertawa lagi... Saya merasa seperti dia telah tertawa lebih banyak kali malam ini daripada sebelumnya.)",
  ui_story_32270401_119_dialog_content = "Aku... Aku rasa aku mengerti sekarang. Ketika orang-orang memiliki makanan yang lezat untuk dimakan, mereka meluangkan waktu karena mereka tidak ingin pengalaman itu berakhir.",
  ui_story_32270401_120_dialog_content = "Dan hanya saat mereka bahagia, mereka benar-benar dapat menikmati rasa makanan.",
  ui_story_32270401_121_dialog_content = "Saat ini, sandwich di tangan saya rasanya sangat lezat.",
  ui_story_32270401_122_dialog_content = "(Aku tidak percaya dia mengatakan semua itu dengan wajah yang begitu bahagia. Itu benar-benar di luar karakternya...)",
  ui_story_32270401_123_dialog_content = "Hmm? Kenapa wajahmu begitu merah? Apakah mungkin kamu tidak kepanasan karena berlarian kesana kemari?",
  ui_story_32270401_124_dialog_content = "I-I-Ini tidak apa-apa! Hahaha... Tidak mungkin sebagus itu, kan? Lagipula, ini hanya sandwich!",
  ui_story_32270401_125_dialog_content = "Jangan makan terlalu banyak, oke? Kita masih bisa kembali ke restoran dan memesan makanan kita.",
  ui_story_32270401_126_dialog_content = "Tidak perlu. Saya sudah makan malam yang paling lezat, semua berkat tuan rumah yang luar biasa.",
  ui_story_32270401_127_dialog_content = "Di sini, PlayerName... Medali ini untukmu.",
  ui_story_32270401_128_dialog_content = "\"Tuuan Rumah Terbaik di Dunia\"? Ini indah... Tunggu, kamu memberikan ini untukku?",
  ui_story_32270401_129_dialog_content = "Ya. Saya harap kamu tidak keberatan, tapi saya membuatnya sendiri.",
  ui_story_32270401_130_dialog_content = "Ah! Jadi ini yang kamu sembunyikan saat aku datang ke kamarmu lebih awal hari ini! Ini juga \"benda sangat penting\" yang mencoba dicuri oleh teman kecil kita...",
  ui_story_32270401_131_dialog_content = "Meong!",
  ui_story_32270401_132_dialog_content = "Benar... Ketika kamu mengundangku makan malam, aku pikir ini adalah kesempatan yang sempurna untuk memberikan ini padamu.",
  ui_story_32270401_133_dialog_content = "Setiap hari yang saya habiskan di Soroz begitu damai dan menyenangkan.",
  ui_story_32270401_134_dialog_content = "Saya merasakan kegembiraan yang tidak pernah saya rasakan sebelumnya, dan itu semua berkat kamu, PlayerName.",
  ui_story_32270401_135_dialog_content = "Tanpa tuan rumah luar biasa seperti Anda, saya tidak akan pernah memiliki liburan yang begitu indah—",
  ui_story_32270401_136_dialog_content = "... Juga, aku tidak akan pernah merasakan kebahagiaan sejati dari makanan untuk pertama kalinya dalam hidupku.",
  ui_story_32270401_137_dialog_content = "Terima kasih. Saya akan selalu mengingat setiap momen waktu saya di atas Colossus.",
  ui_story_32270401_138_dialog_content = "Rachel!",
  ui_story_32270401_139_dialog_content = "Baiklah, maka sudah diputuskan! Mulai besok, pembawa acara terhebat di dunia akan menunjukkan kepada Anda semua hal menakjubkan yang ditawarkan oleh Astra!",
  ui_story_32270401_140_dialog_content = "H-Hah?",
  ui_story_32270401_141_dialog_content = "Dan kita akan mulai dengan balapan di Gurun Rediesel! Pegangan erat—",
  ui_story_32270401_142_dialog_content = "Tunggu, tenanglah sedikit!",
  ui_story_32270601_1_dialog_content = "<color=#e8d9bb>cipratan... cipratan...</color>",
  ui_story_32270601_2_dialog_content = "Aneh...",
  ui_story_32270601_3_dialog_content = "Mengapa pantai di sini tidak ramai sama sekali?",
  ui_story_32270601_4_dialog_content = "Bukankah pantai seharusnya ramai dengan orang-orang pada waktu tahun ini...?",
  ui_story_32270601_5_dialog_content = "(Bisakah jadi... Aku salah paham tentang niat Reinhardt?)",
  ui_story_32270601_6_dialog_content = "Sekarang aku punya \"quest\" yang ingin kuserahkan padamu, PlayerName.",
  ui_story_32270601_7_dialog_content = "Tentu saja, ada hadiah.",
  ui_story_32270601_8_dialog_content = "Bukankah kita teman...? Kenapa tiba-tiba begitu formal, ini membuatku sedikit gugup...",
  ui_story_32270601_9_dialog_content = "Haha! Ini bukanlah misi yang terlalu sulit, tapi...",
  ui_story_32270601_10_dialog_content = "Aku butuh kamu untuk menemani Rachel ke pantai dan pastikan dia memiliki waktu yang baik. Itu saja. Aku mengandalkanmu.",
  ui_story_32270601_11_dialog_content = "Caelestite Satu... Ah, tidak, seharusnya aku memanggilmu PlayerName.",
  ui_story_32270601_12_dialog_content = "Terima kasih sudah meluangkan waktu untuk datang dan bergabung denganku dalam pencarian ini.",
  ui_story_32270601_13_dialog_content = "Su... Sungguh sebuah quest...?",
  ui_story_32270601_14_dialog_content = "Tapi pakaian Rachel hari ini... sepertinya dia tidak sedang dalam misi?",
  ui_story_32270601_15_dialog_content = "Ini... Aku pergi ke Umbraton khusus untuk menyusup ke pantai.",
  ui_story_32270601_16_dialog_content = "Presiden Guild yang tinggi secara pribadi memilihkan baju renang untuk saya.",
  ui_story_32270601_17_dialog_content = "Dia bilang ini adalah item musiman terbaru, dijamin akan cocok sempurna dengan suasana pantai, tapi...",
  ui_story_32270601_18_dialog_content = "Apakah ini pertama kalinya kamu menyadari... betapa memalukannya memakai baju renang?",
  ui_story_32270601_19_dialog_content = "(Presiden guild yang tinggi, apakah itu Nona Sheol...)",
  ui_story_32270601_20_dialog_content = "(Setelan renang ini... Ini pasti gaya yang akan dia rekomendasikan...)",
  ui_story_32270601_21_dialog_content = "Jangan malu, kamu terlihat sangat bagus dalam hal itu, Rachel.",
  ui_story_32270601_22_dialog_content = "Tidak ada baju renang di pantai ini yang lebih indah daripada milikmu!",
  ui_story_32270601_23_dialog_content = "Tidak ada... orang lain di sini, kan...",
  ui_story_32270601_24_dialog_content = "*Batuk* Sebenarnya, saya bertanya-tanya mengapa tidak ada orang lain di sini...",
  ui_story_32270601_25_dialog_content = "Hmm, sepertinya ini adalah area yang terbengkalai.",
  ui_story_32270601_26_dialog_content = "T-Tanah tak bertuan?!",
  ui_story_32270601_27_dialog_content = "Saya juga baru saja menggunakan drone untuk mengintai medan pantai dan sampai pada kesimpulan ini.",
  ui_story_32270601_28_dialog_content = "Grand Marshal secara khusus mengirimku berlibur ke tempat ini, dia mungkin masih berharap bahwa aku bisa menghasilkan laporan survei.",
  ui_story_32270601_29_dialog_content = "Kata-kata dari Marsekal Agung...",
  ui_story_32270601_30_dialog_content = "Tidak, tidak, tidak, dia pasti ingin kamu menikmati liburanmu, itulah sebabnya dia membawamu ke sini!",
  ui_story_32270601_31_dialog_content = "Benarkah?",
  ui_story_32270601_32_dialog_content = "Jika ini benar-benar liburan, saya tidak tahu apa yang harus saya lakukan.",
  ui_story_32270601_33_dialog_content = "Sebaliknya, melanjutkan untuk menjalankan quest memberikan rasa kenyamanan dan kelegaan.",
  ui_story_32270601_34_dialog_content = "Kalau saja ada anak kucing di pantai...",
  ui_story_32270601_35_dialog_content = "Uh... Jika kita sedang berlibur, terutama di pantai, sebenarnya ada banyak hal yang bisa kita lakukan...",
  ui_story_32270601_36_dialog_content = "Ngomong-ngomong, aku sudah penasaran sejak lama, PlayerName, kamu membawa tas besar...",
  ui_story_32270601_37_dialog_content = "Apakah ini tempat item quest disimpan?",
  ui_story_32270601_38_dialog_content = "Untuk mengatakannya dengan tepat... Saya kira begitu!",
  ui_story_32270601_39_dialog_content = "<color=#e8d9bb>Klink, denting!</color>",
  ui_story_32270601_40_dialog_content = "Bola latihan fisik, senjata simulasi pertempuran, dan buah hidrasi untuk meredakan panas?",
  ui_story_32270601_41_dialog_content = "Jika kita berspekulasi berdasarkan ini, misi PlayerName seharusnya—",
  ui_story_32270601_42_dialog_content = "*Batuk*... Ini voli pantai, senjata air, dan semangka!",
  ui_story_32270601_43_dialog_content = "Untuk lebih tepatnya, ini semua adalah barang-barang penting untuk liburan pantai!",
  ui_story_32270601_44_dialog_content = "Jadi, PlayerName, apakah kamu sudah memutuskan untuk datang dan bergabung denganku dalam liburan sebelumnya?",
  ui_story_32270601_45_dialog_content = "Lagi pula, ini musim panas... pantai... tidak peduli bagaimana kamu memikirkannya, ini harusnya liburan, kan!?",
  ui_story_32270601_46_dialog_content = "Itu sangat khas kamu, PlayerName. Jika bukan karena kamu, mungkin aku salah paham dengan niat Grand Marshal.",
  ui_story_32270601_47_dialog_content = "Berdasarkan pengalamanmu, aktivitas apa yang harus kita lakukan sekarang?",
  ui_story_32270601_48_option_content = "Bagaimana kalau kita bermain voli pantai?",
  ui_story_32270601_49_dialog_content = "Bola voli... Ini adalah olahraga yang belum pernah saya temui sebelumnya.",
  ui_story_32270601_50_dialog_content = "Jika kamu memilih ini, aku khawatir kamu harus berlatih denganku, PlayerName.",
  ui_story_32270601_51_dialog_content = "Jadi, sebenarnya saya lebih suka senjata air...",
  ui_story_32270601_52_option_content = "Bagaimana jika kita bermain dengan pistol air?",
  ui_story_32270601_53_dialog_content = "Pistol air? Ini cukup mirip dengan senjata yang telah saya gunakan.",
  ui_story_32270601_54_dialog_content = "Bahkan efek pemadaman suara ini tak bisa dicela.",
  ui_story_32270601_55_dialog_content = "Tapi agak tidak adil pada PlayerName...",
  ui_story_32270601_56_dialog_content = "Tunggu, tunggu, tunggu, tunggu, kita benar-benar harus bersaing?!",
  ui_story_32270601_57_dialog_content = "Pastikan untuk melihat acara ini sebagai kompetisi.",
  ui_story_32270601_58_dialog_content = "Jika saya harus bersaing melawan Anda, PlayerName, saya bisa belajar banyak.",
  ui_story_32270601_59_dialog_content = "(Saya merasa seperti Rachel masih belum bisa melepaskan diri... Apakah karena dia jarang beristirahat...?)",
  ui_story_32270601_60_dialog_content = "(Aku benar-benar perlu membuatnya merasa lebih terlibat!)",
  ui_story_32270601_61_dialog_content = "Maka saya akan pergi terlebih dahulu, pistol air premium berkapasitas tinggi ini adalah milik saya!",
  ui_story_32270601_62_dialog_content = "Merasa bebas, PlayerName. Lagipula, jika berbicara tentang keterampilan menembak, saya cukup yakin.",
  ui_story_32270601_63_dialog_content = "Hmph, bermain dengan senjata air tidak selalu memerlukan keterampilan menembak, misalnya...",
  ui_story_32270601_64_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_32270601_65_dialog_content = "Tidak masalah melancarkan serangan diam-diam meskipun itu tidak terhormat.",
  ui_story_32270601_66_dialog_content = "...",
  ui_story_32270601_67_dialog_content = "Eh... Apa kita tidak seharusnya mulai melawan pada titik ini?",
  ui_story_32270601_68_dialog_content = "Tapi, menodongkan senapan ke PlayerName, itu sedikit...",
  ui_story_32270601_69_dialog_content = "Ini adalah pistol air, Rachel.",
  ui_story_32270601_70_dialog_content = "Dan bukankah ini yang dipilih oleh Rachel? Kaulah yang menyarankan kontes, jadi...",
  ui_story_32270601_71_dialog_content = "<color=#e8d9bb>Mendesis—Mendesis—</color>",
  ui_story_32270601_72_dialog_content = "Jadi meskipun kamu tidak melakukan serangan balik, saya tidak akan berhenti!",
  ui_story_32270601_73_dialog_content = "Tunggu, tunggu!",
  ui_story_32270601_74_dialog_content = "Aku tidak akan berhenti sampai Rachel mengaku kalah!!",
  ui_story_32270601_75_dialog_content = "Yang kalah akan kehilangan hak untuk membagikan semangka, siap-siap!!!",
  ui_story_32270601_76_dialog_content = "Saya tidak keberatan dengan semangka, tapi menjadi satu-satunya yang basah kuyup cukup memalukan...",
  ui_story_32270601_77_dialog_content = "Saya akan melakukan serangan balik, PlayerName.",
  ui_story_32270601_78_dialog_content = "<color=#e8d9bb>Wusss...</color>",
  ui_story_32270601_79_dialog_content = "Senapan ini ...",
  ui_story_32270601_80_dialog_content = "Kelihatannya mengagumkan, tapi apakah \"kekuatannya\" benar-benar selemah itu?",
  ui_story_32270601_81_dialog_content = "Aku perlu memikirkan sesuatu...",
  ui_story_32270601_82_dialog_content = "Hehe, jangan salahkan aku... Ambil ini!",
  ui_story_32270601_83_dialog_content = "<color=#e8d9bb>Mendesis—Mendesis—</color>",
  ui_story_32270601_84_dialog_content = "Uh oh... Aku telah dipukul berulang kali...",
  ui_story_32270601_85_dialog_content = "Jadi, PlayerName bisa sejahat ini...?",
  ui_story_32270601_86_dialog_content = "Humph, sepertinya Rachel masih belum mengerti cara bertahan hidup di pantai!",
  ui_story_32270601_87_dialog_content = "Nah, aku sudah menang sekarang! Aku adalah Legenda Pantai, Raja Pistol Air! Ambil ini—",
  ui_story_32270601_88_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_32270601_89_dialog_content = "Huh... Kenapa tiba-tiba ada hawa dingin di punggung saya?",
  ui_story_32270601_90_dialog_content = "PlayerName bilang tak apa-apa meski kita tidak membicarakan tentang etika bela diri dan penyergapan, bukan?",
  ui_story_32270601_91_dialog_content = "Sepertinya... mungkin aku telah mengatakan sesuatu seperti itu, tapi...",
  ui_story_32270601_92_dialog_content = "Bagaimana kamu bisa menembakku dari belakang...?",
  ui_story_32270601_93_dialog_content = "<color=#e8d9bb>PlayerName berbalik, berhadapan langsung dengan tiga drone yang dilengkapi dengan senjata air.</color>",
  ui_story_32270601_94_dialog_content = "<color=#e8d9bb>Mengelilinginya sepenuhnya, tanpa ada titik buta.</color>",
  ui_story_32270601_95_dialog_content = "Jadi, kamu tidak bilang dia tidak bisa meminta bantuan, kan?",
  ui_story_32270601_96_dialog_content = "Tunggu, tunggu, tunggu, jika saya menggunakan Pemburu Elang...",
  ui_story_32270601_97_dialog_content = "Tidak usah khawatir, semua modul tempur telah dimatikan. Sekarang kita berada dalam mode fokus pistol semprot.",
  ui_story_32270601_98_dialog_content = "Kamu baru saja bilang \"Ini hanya senjata air\", bukan masalah besar.",
  ui_story_32270601_99_dialog_content = "Kenapa... Kenapa aku tidak ingat mengucapkan kata-kata yang tidak bertanggung jawab seperti itu?",
  ui_story_32270601_100_dialog_content = "Serangan talon!",
  ui_story_32270601_101_dialog_content = "<color=#e8d9bb>Desis—<size=50>Desis, desis, desis, desis, desis—!</size></color>",
  ui_story_32270601_102_dialog_content = "B-bantu!!",
  ui_story_32270601_103_dialog_content = "<color=#e8d9bb>Pada akhirnya, di tengah pengejaran drone dan tawa ceria Rachel...</color>",
  ui_story_32270601_104_dialog_content = "<color=#e8d9bb>\"Caelestite Terakhir\", \"Raja Pistol Air\", \"Legenda Pantai\" — PlayerName.</color>",
  ui_story_32270601_105_dialog_content = "<color=#e8d9bb>Menyambut kekalahan paling brutal di musim panas ini...</color>"
}
return config
